const {chromium}=require('playwright');const fs=require('fs');let pass=0,fail=0;const ok=(c,m)=>{if(c)pass++;else{fail++;console.log('FAIL',m)}};
(async()=>{const b=await chromium.launch();const c=await b.newContext({viewport:{width:820,height:1100}});const p=await c.newPage();const errs=[];p.on('pageerror',e=>errs.push(p.url().split('/').pop()+': '+e.message.slice(0,150)));
await p.route(/cdnjs\.cloudflare\.com.*react-dom/,r=>r.fulfill({body:fs.readFileSync('/tmp/da/node_modules/react-dom/umd/react-dom.production.min.js'),contentType:'application/javascript'}));
await p.route(/cdnjs\.cloudflare\.com.*\/react\//,r=>r.fulfill({body:fs.readFileSync('/tmp/da/node_modules/react/umd/react.production.min.js'),contentType:'application/javascript'}));
await p.route(/googletagmanager|fonts\.g/,r=>r.abort());
const B='http://localhost:8855/';
await p.goto(B+'teacher-dashboard.html');await p.waitForTimeout(3000);
const chips=await p.$$eval('[data-testid=name-chip]',es=>es.map(e=>e.textContent));ok(chips.slice(0,3).join()==='Mia3:30 PM,Leo4:30 PM,Avamakeup','chips '+chips);
await p.screenshot({path:'1-chips.png'});
await p.click('[data-testid=name-chip]:has-text("Mia")');await p.waitForTimeout(1500);
ok(await p.isVisible('[data-testid=start-lesson]'),'start button');await p.screenshot({path:'2-detail.png'});
await p.click('[data-testid=start-lesson]');await p.waitForURL(/drills\.html/);await p.waitForTimeout(4000);
ok(await p.isVisible('[data-testid=lesson-bar]'),'lesson bar');ok(/Lesson with Mia · 0 shown/.test(await p.textContent('[data-testid=lesson-bar]')),'bar 0');
await p.goto(B+'drills.html?drill=key-signatures&tab=learn');await p.waitForTimeout(3500);
await p.goto(B+'drills.html?view=tools&tool=scale-finder');await p.waitForTimeout(3500);
ok(/2 shown/.test(await p.textContent('[data-testid=lesson-bar]')),'bar 2: '+await p.textContent('[data-testid=lesson-bar]'));
await p.screenshot({path:'3-drills.png'});
const L=await p.evaluate(()=>localStorage.getItem('pb_lesson_v1'));console.log('lesson',L);
await p.click('[data-testid=lesson-bar-end]');await p.waitForURL(/teacher-dashboard/);await p.waitForTimeout(3000);
ok(await p.isVisible('[data-testid=end-lesson]'),'end sheet');
const items=await p.$$eval('[data-testid=end-item]',es=>es.map(e=>(e.querySelector('input').checked?'[x] ':'[ ] ')+e.textContent));console.log(items);
ok(items.some(x=>/^\[x\] Key Signatures/.test(x)),'room checked');ok(items.some(x=>/^\[ \] Scale finder/.test(x)),'tool unchecked');ok(items.some(x=>/^\[x\] Minuet in G, bars 1-8 \(again\)/.test(x)),'again checked');
await p.screenshot({path:'4-end.png'});
await p.fill('[data-testid=end-notes]','Sharps in order, good.');await p.click('[data-testid=end-save]');await p.waitForTimeout(1200);
ok(!(await p.$('[data-testid=end-lesson]')),'sheet closed');ok(!(await p.evaluate(()=>localStorage.getItem('pb_lesson_v1'))),'lesson cleared');
const log=await p.evaluate(()=>window.__DB.lesson_logs[window.__DB.lesson_logs.length-1]);const ex=JSON.parse(log.extra);console.log(ex);
ok(/Key Signatures \[chapter:key-signatures\]/.test(ex.homework)&&/Minuet in G, bars 1-8/.test(ex.homework)&&!/scale-finder/.test(ex.homework),'homework lines');ok(ex.shown&&ex.shown.length===2,'shown saved');ok(log.notes==='Sharps in order, good.','notes');
await p.click('[data-testid=name-chip]:has-text("Mia")');await p.waitForTimeout(1500);ok(/Key Signatures/.test(await p.textContent('[data-testid=last-shown]')),'last lesson shows Shown');
await p.screenshot({path:'5-after.png'});
ok(errs.length===0,'errors '+errs.join(' | '));await b.close();console.log('pass',pass,'fail',fail)})();
